/*
 * ESP32 Deep Sleep - Timer Wakeup
 *
 * The ESP32 prints a banner, blinks the LED once, then goes to deep sleep
 * for 5 seconds. On wake it boots again from setup() and prints the wakeup
 * cause reported by esp_sleep_get_wakeup_cause().
 *
 * Deep sleep clears normal RAM, so bootCount restarts at 1 on every wake -
 * exactly what real hardware does. The wakeup cause is the reliable way to
 * tell that you actually slept.
 *
 * Try it:
 *   - Comment out esp_sleep_enable_timer_wakeup() and re-run: with no
 *     wakeup source configured the device stays asleep forever.
 */

#include <esp_sleep.h>

int bootCount = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED_BUILTIN, OUTPUT);

  bootCount++;
  Serial.println();
  Serial.println("=== ESP32 booted ===");
  Serial.print("Boot number: ");
  Serial.println(bootCount);

  Serial.print("Wakeup cause: ");
  Serial.println(esp_sleep_get_wakeup_cause());

  // One blink so each boot is visible on the board too
  digitalWrite(LED_BUILTIN, HIGH);
  delay(200);
  digitalWrite(LED_BUILTIN, LOW);

  Serial.println("Going to deep sleep for 5000 ms ...");
  esp_sleep_enable_timer_wakeup(5000000);   // 5,000,000 microseconds
  esp_deep_sleep_start();                   // does not return
}

void loop() {
  // Never reached - esp_deep_sleep_start() powers down the chip
}
